    fun printUpgradeNotes(): String {
        val sb = StringBuilder()
        sb.appendLine("=== S Engine Ultimate Edition 6.1.2 [Ultra] Most Powerful Ultra Edition ===")
        sb.appendLine("Version: $VERSION | API: $API_VERSION | Date: $RELEASE_DATE")
        sb.appendLine("Previous: $PREV_VERSION [$PREV_CODENAME]")
        sb.appendLine("\nUltra Core Features (${ultraCoreFeatures.size}):")
        ultraCoreFeatures.forEachIndexed { i, f -> sb.appendLine("${i+1}. $f") }
        sb.appendLine("\nProfessional Months/Years Features (${ultraProfessionalMonthsYears.size}):")
        ultraProfessionalMonthsYears.forEachIndexed { i, f -> sb.appendLine("${i+1}. $f") }
        return sb.toString()
